const fs = require('fs');
const readline = require('readline');

async function searchTranscripts() {
  const fileStream = fs.createReadStream('C:/Users/phons/.gemini/antigravity/brain/39386585-9744-4129-87ca-5e2c355221c2/.system_generated/logs/transcript_full.jsonl');
  const rl = readline.createInterface({ input: fileStream, crlfDelay: Infinity });

  let lineNum = 0;
  for await (const line of rl) {
    lineNum++;
    if (line.includes('KanbanBoard') || line.includes('TeamRosterView')) {
      if (line.includes('function KanbanBoard') || line.includes('function TeamRosterView') || line.includes('KanbanBoard =')) {
        console.log(`[Line ${lineNum}] Found match! Line snippet:`, line.substring(0, 300));
        fs.writeFileSync(`d:/Team Projects/js/match_${lineNum}.json`, line, 'utf8');
      }
    }
  }
}

searchTranscripts();
